/**
 * Links generated by the platform (invite / "new access link") come back as
 *   /<hotel>?convite=1#access_token=…&refresh_token=…&type=invite
 * or, when expired/used, as  #error=access_denied&error_code=otp_expired&error_description=…
 *
 * The portal routes live in the hash too, so this runs before anything reads it (imported first in
 * main.tsx): it keeps the tokens in memory only, removes them from the address bar and history,
 * and sends the user to the admin login, which finishes the setup (2FA + password).
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { authMessage, LAST_ACTIVITY_KEY, RECOVERY_KEY } from './adminAuth';

export type PendingAuthLink = { kind: 'session'; accessToken: string; refreshToken: string } | { kind: 'error'; message: string };

let pending: PendingAuthLink | null = null;

const ERRORS: Record<string, string> = {
  otp_expired: 'Este link de acesso expirou ou já foi usado. Peça um novo ao suporte da plataforma.',
  access_denied: 'Link de acesso inválido. Peça um novo ao suporte da plataforma.',
};

(function capture() {
  const hash = window.location.hash.replace(/^#\/?/, '');
  if (!/(^|&)(access_token|error)=/.test(hash)) return;
  const p = new URLSearchParams(hash);
  const accessToken = p.get('access_token');
  const refreshToken = p.get('refresh_token');
  if (accessToken && refreshToken) pending = { kind: 'session', accessToken, refreshToken };
  else
    pending = {
      kind: 'error',
      message: ERRORS[p.get('error_code') ?? ''] ?? ERRORS[p.get('error') ?? ''] ?? (p.get('error_description') || 'Link inválido.'),
    };
  const url = new URL(window.location.href);
  url.searchParams.delete('convite');
  history.replaceState(null, '', `${url.pathname}${url.search}#/admin`);
})();

let applied: Promise<{ applied: boolean; error?: string }> | null = null;

/**
 * Signs in with the captured link (once — the tokens are single-use; later calls get the same result).
 * The session then still needs 2FA, and RECOVERY_KEY makes the login ask the invitee to create a password.
 */
export function applyPendingAuthLink(db: SupabaseClient) {
  applied ??= (async () => {
    const link = pending;
    pending = null;
    if (!link) return { applied: false };
    if (link.kind === 'error') return { applied: false, error: link.message };
    localStorage.setItem(LAST_ACTIVITY_KEY, String(Date.now())); // fresh sign-in, not an idle session
    await db.auth.signOut({ scope: 'local' }); // never mix with whoever was signed in on this browser
    const { error } = await db.auth.setSession({ access_token: link.accessToken, refresh_token: link.refreshToken });
    if (error) return { applied: false, error: authMessage(error) };
    sessionStorage.setItem(RECOVERY_KEY, '1');
    return { applied: true };
  })();
  return applied;
}
